contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit `amount` into c, then call withdrawAll once and assert the stated invariant.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // deposit amount into c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // observe balances before withdraw
        uint cBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;

        // call withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe balances after withdraw
        uint cBalAfter = address(c).balance;
        uint myBalAfter = address(this).balance;

        // If reverted: balances unchanged. If returned: this contract's balance increased by exactly amount and c's balance decreased by exactly amount.
        assert(
            (reverted && cBalAfter == cBalBefore && myBalAfter == myBalBefore)
            || (!reverted && myBalAfter == myBalBefore + amount && cBalAfter + amount == cBalBefore)
        );
    }

    // allow receiving Ether during C.withdrawAll's external call
    receive() external payable {}
}

